"""Task-local helper: prepend a cover page to report.pdf.

Creates a single-page cover with the exact title 'Annual Financial Report'
and the current date, then prepends it to report.pdf in place, using only
pure-Python PDF handling (no third-party libraries required).

The original PDF's objects are copied verbatim, so all content and
references stay valid. Only report.pdf is transformed; temporary
cover/output files are removed.
"""

import datetime
import os
import re
import sys

TITLE = "Annual Financial Report"
MAX_PARSE_STEPS = 1_000_000


# ---------------------------------------------------------------------------
# Minimal PDF object parsing (dicts, arrays, refs, numbers, strings, names).
# ---------------------------------------------------------------------------

def _parse_value(data, pos):
    n = len(data)
    while pos < n and data[pos] in b" \t\r\n":
        pos += 1
    if pos >= n:
        return None, pos
    c = data[pos]
    if c == 0x3C:  # '<'
        if data[pos:pos + 2] == b"<<":
            return _parse_dict(data, pos)
        end = data.find(b">", pos)
        if end == -1:
            return data[pos + 1:], n
        return data[pos + 1:end], end + 1
    if c == 0x28:  # '(' literal string
        depth = 1
        i = pos + 1
        while i < n and depth:
            ch = data[i:i + 1]
            if ch == b"\\":
                i += 2
                continue
            if ch == b"(":
                depth += 1
            elif ch == b")":
                depth -= 1
            i += 1
        return data[pos:i], i
    if c == 0x5B:  # '['
        arr = []
        i = pos + 1
        while i < n:
            while i < n and data[i] in b" \t\r\n":
                i += 1
            if i < n and data[i:i + 1] == b"]":
                return arr, i + 1
            v, i = _parse_value(data, i)
            arr.append(v)
        return arr, i
    # number, name, or indirect reference
    m = re.match(rb"(\d+)\s+(\d+)\s+R", data[pos:])
    if m:
        return (int(m.group(1)), int(m.group(2))), pos + len(m.group(0))
    start = pos
    while pos < n and data[pos] not in b" \t\r\n[]<>()/":
        pos += 1
    tok = data[start:pos]
    if tok.startswith(b"/"):
        return tok, pos
    return tok, pos


def _parse_dict(data, pos):
    while pos < len(data) and data[pos] in b" \t\r\n":
        pos += 1
    obj = {}
    i = pos + 2
    steps = 0
    while True:
        steps += 1
        if steps > MAX_PARSE_STEPS:
            raise RuntimeError("dict parse exceeded step limit")
        if i >= len(data):
            return obj, i
        while i < len(data) and data[i] in b" \t\r\n":
            i += 1
        if i < len(data) and data[i:i + 2] == b">>":
            return obj, i + 2
        key, i2 = _parse_value(data, i)
        if not isinstance(key, bytes) or not key.startswith(b"/"):
            if i2 >= len(data):
                return obj, i2
            i = i2 + 1
            continue
        val, i = _parse_value(data, i2)
        obj[key[1:]] = val


def _parse_xref(data):
    m = re.search(rb"startxref\s+(\d+)", data)
    if not m:
        return None
    xref_pos = int(m.group(1))
    if data[xref_pos:xref_pos + 4] != b"xref":
        return None
    entries = {}
    pos = xref_pos + 4
    while True:
        while pos < len(data) and data[pos] in b" \t\r\n":
            pos += 1
        if pos < len(data) and data[pos:pos + 2] == b"tr":
            break
        m = re.match(rb"(\d+)\s+(\d+)", data[pos:])
        if not m:
            break
        start, count = int(m.group(1)), int(m.group(2))
        pos += m.end()
        for i in range(count):
            while pos < len(data) and data[pos] in b" \t\r\n":
                pos += 1
            entry = data[pos:pos + 20]
            parts = entry.split()
            if len(parts) >= 3 and parts[2] == b"n":
                entries[start + i] = int(parts[0])
            pos += 20
    # Advance past the 'trailer' keyword to the trailer dictionary.
    while pos < len(data) and data[pos] != 0x3C:
        pos += 1
    if pos >= len(data):
        return entries, -1
    return entries, pos


def _load_objects(data):
    """Return {obj_num: content_bytes} using the xref table."""
    parsed = _parse_xref(data)
    if parsed is None:
        # Fallback: scan for object headers.
        offsets = {}
        for m in re.finditer(rb"(\d+)\s+0\s+obj", data):
            offsets[int(m.group(1))] = m.start()
    else:
        offsets = parsed[0]
    if not offsets:
        return None
    ordered = sorted(offsets.items())
    objects = {}
    for idx, (num, off) in enumerate(ordered):
        end = ordered[idx + 1][1] if idx + 1 < len(ordered) else len(data)
        body = data[off:end]
        hdr_end = body.find(b"obj") + 3
        if hdr_end < 3:
            continue
        endobj = body.rfind(b"endobj")
        if endobj == -1:
            endobj = len(body)
        content = body[hdr_end:endobj]
        if len(content) > 64 * 1024 * 1024:  # sanity cap on a single object
            content = content[: 64 * 1024 * 1024]
        objects[num] = content
    return objects


def _resolve_ref(value):
    return value[0] if isinstance(value, tuple) else None


def _count_pages(objects, pages_num):
    """Depth-first count of leaf pages under a /Pages node."""
    count = 0
    seen = set()
    stack = [pages_num]
    while stack:
        num = stack.pop()
        if num in seen or num not in objects:
            continue
        seen.add(num)
        try:
            d, _ = _parse_dict(objects[num], 0)
        except Exception:
            count += 1  # cannot parse: treat as leaf
            continue
        if b"Kids" in d:
            for kid in d[b"Kids"]:
                ref = _resolve_ref(kid)
                if ref is not None:
                    stack.append(ref)
        else:
            count += 1
    return count


def _escape_pdf_string(s):
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


